CREATE PROCEDURE "SBO_EXX_SIRE_ASISTENTE_MASIVO" ( IN TIPO VARCHAR (1) , IN PROCESO VARCHAR (1) , IN PERIODO VARCHAR (1) ) AS BEGIN
IF :TIPO = 'C' THEN IF :PROCESO = '-' THEN SELECT (CASE WHEN IFNULL(T2."DocEntry", 0) = 0 THEN 'N' ELSE 'Y' END) AS "Sel", T0."Code" AS "BPLId", T1."GlblLocNum", T1."BPLName" AS "BPLName", T0."U_EXX_APIS", T0."U_EXX_USER", T0."U_EXX_PASS", T0."U_EXX_CLID", T0."U_EXX_CLSE", IFNULL(T2."DocEntry", 0) "DocEntry" FROM "@EXX_SIRE_APIS" T0 INNER JOIN "OBPL" T1 ON T0."Code" = T1."BPLId" LEFT JOIN "@EXX_SIRE_COMP" T2 ON T0."Code" = T2."U_EXX_BPLID" AND IFNULL(T2."Canceled", 'N') = 'N' AND T2."U_EXX_PERIODO" = :PERIODO WHERE IFNULL(T0."U_EXX_APIS", '') <> '' AND IFNULL(T0."U_EXX_USER", '') <> '' AND IFNULL(T0."U_EXX_PASS", '') <> '' AND IFNULL(T0."U_EXX_CLID", '') <> '' AND IFNULL(T0."U_EXX_CLSE", '') <> ''; ELSE
SELECT (CASE WHEN IFNULL(T2."DocEntry", 0) = 0 THEN 'N' ELSE 'Y' END) AS "Sel", T0."Code" AS "BPLId", T1."GlblLocNum", T1."BPLName" AS "BPLName", T0."U_EXX_APIS", T0."U_EXX_USER", T0."U_EXX_PASS", T0."U_EXX_CLID", T0."U_EXX_CLSE", IFNULL(T2."DocEntry", 0) "DocEntry" FROM "@EXX_SIRE_APIS" T0 INNER JOIN "OBPL" T1 ON T0."Code" = T1."BPLId" LEFT JOIN "@EXX_SIRE_COMP" T2 ON T0."Code" = T2."U_EXX_BPLID" AND IFNULL(T2."Canceled", 'N') = 'N' AND T2."U_EXX_PERIODO" = :PERIODO WHERE IFNULL(T0."U_EXX_APIS", '') <> '' AND IFNULL(T0."U_EXX_USER", '') <> '' AND IFNULL(T0."U_EXX_PASS", '') <> '' AND IFNULL(T0."U_EXX_CLID", '') <> '' AND IFNULL(T0."U_EXX_CLSE", '') <> '' AND T2."U_EXX_ESTADO" = :PROCESO; END IF;
ELSEIF :TIPO = 'V' THEN IF :PROCESO = '-' THEN SELECT (CASE WHEN IFNULL(T2."DocEntry", 0) = 0 THEN 'N' ELSE 'Y' END) AS "Sel", T0."Code" AS "BPLId", T1."GlblLocNum", T1."BPLName" AS "BPLName", T0."U_EXX_APIS", T0."U_EXX_USER", T0."U_EXX_PASS", T0."U_EXX_CLID", T0."U_EXX_CLSE", IFNULL(T2."DocEntry", 0) "DocEntry" FROM "@EXX_SIRE_APIS" T0 INNER JOIN "OBPL" T1 ON T0."Code" = T1."BPLId" LEFT JOIN "@EXX_SIRE_VENT" T2 ON T0."Code" = T2."U_EXX_BPLID" AND IFNULL(T2."Canceled", 'N') = 'N' AND T2."U_EXX_PERIODO" = :PERIODO WHERE IFNULL(T0."U_EXX_APIS", '') <> '' AND IFNULL(T0."U_EXX_USER", '') <> '' AND IFNULL(T0."U_EXX_PASS", '') <> '' AND IFNULL(T0."U_EXX_CLID", '') <> '' AND IFNULL(T0."U_EXX_CLSE", '') <> '';
ELSE SELECT (CASE WHEN IFNULL(T2."DocEntry", 0) = 0 THEN 'N' ELSE 'Y' END) AS "Sel", T0."Code" AS "BPLId", T1."GlblLocNum", T1."BPLName" AS "BPLName", T0."U_EXX_APIS", T0."U_EXX_USER", T0."U_EXX_PASS", T0."U_EXX_CLID", T0."U_EXX_CLSE", IFNULL(T2."DocEntry", 0) "DocEntry" FROM "@EXX_SIRE_APIS" T0 INNER JOIN "OBPL" T1 ON T0."Code" = T1."BPLId" LEFT JOIN "@EXX_SIRE_VENT" T2 ON T0."Code" = T2."U_EXX_BPLID" AND IFNULL(T2."Canceled", 'N') = 'N' AND T2."U_EXX_PERIODO" = :PERIODO WHERE IFNULL(T0."U_EXX_APIS", '') <> '' AND IFNULL(T0."U_EXX_USER", '') <> '' AND IFNULL(T0."U_EXX_PASS", '') <> '' AND IFNULL(T0."U_EXX_CLID", '') <> '' AND IFNULL(T0."U_EXX_CLSE", '') <> '' AND T2."U_EXX_ESTADO" = :PROCESO; END IF; END IF; END;
